import { useAuth0 } from "@auth0/auth0-react";

const LogoutButton = () => {
    const { logout } = useAuth0();

    return (
        <button onClick={() => logout({ logoutParams: { returnTo: window.location.origin } })} className="btn btn-outline-light">
            Log Out
        </button>
    )
}
export default LogoutButton
